create table RB_TAE_ACCOUNT_CHECK_SUM (SESSION_ID VARCHAR(20) not null  ,CRET_TOTAL_NUM INT null  ,CRET_TOTAL_AMT DECIMAL(38,2) null  ,DEBT_TOTAL_NUM INT null  ,DEBT_TOTAL_AMT DECIMAL(17,2) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  , primary key(SESSION_ID));